class CommercialPropertyApartmentUnit(BaseModel):
    id: int | None = None
    """
    Unique identifier for the apartment unit record.
    """
    numBeds: conint(ge=0, le=255) | None = None
    """
    Number of bedrooms in the unit; a primary multifamily unit-mix attribute used to classify and price rental inventory. For student housing, total beds = units x bedrooms.
    """
    numBaths: float | None = None
    """
    Total number of bathrooms in the unit, expressed as a fraction to allow half-baths; a key multifamily unit-mix attribute.
    """
    numFloors: int | None = None
    """
    Number of floors/levels the individual unit spans (e.g. for a townhome or loft), not the building height.
    """
    minSquareFeet: int | None = None
    """
    Lower bound of the unit's rentable area in square feet; ranges accommodate variation across like floor plans.
    """
    maxSquareFeet: int | None = None
    """
    Upper bound of the unit's rentable area in square feet.
    """
    unitNumber: str | None = None
    """
    Identifier label of the specific unit within the building (e.g. apartment/suite number).
    """
    unitName: str | None = None
    """
    Display name of the unit or floor-plan model used in marketing.
    """
    unitDescription: str | None = None
    """
    Free-text marketing description of the unit and its features.
    """
    floorNumber: str | None = None
    """
    Floor on which the unit is located, stored as free text to allow labels like ground, basement, or PH.
    """
    buildingName: str | None = None
    """
    Name of the building containing the unit within a multi-building community.
    """
    isShortTermLeaseAvailable: bool | None = None
    """
    Whether short-term (e.g. month-to-month or under a year) leasing is offered for the unit.
    """
    minLeaseTermsMonths: conint(ge=0, le=255) | None = None
    """
    Minimum lease term offered for the unit in months.
    """
    maxLeaseTermsMonths: conint(ge=0, le=255) | None = None
    """
    Maximum lease term offered for the unit in months.
    """
    nonstandardApartmentRoomType: NonstandardApartmentRoomType | None = None
    """
    Classification for non-standard room configurations (e.g. studio, loft) that fall outside the standard bedroom count.
    """
    residentialProfile: CommercialPropertyResidentialProfile3 | None = None
    """
    Foreign key to the parent residential property/community profile the unit belongs to. Residential profile looked up by this record's profile id.
    """
    availabilityUrl: AnyUrl | None = None
    """
    External link to the unit's live availability or application page. Text converted to a web address; null when absent.
    """
    address: CommercialPropertyAddress | None = None
    """
    Foreign key to the address record for the unit's location; join on the integer ID. Address looked up by the unit's address id; null when the unit has no address id.
    """
    amenities: list[CommercialPropertyAmenityReference] | None = None
    """
    Collection of amenity references describing features offered with the unit.
    """
    attachments: list[CommercialPropertyAttachmentReference2] | None = None
    """
    Collection of media attachment references (photos, etc.) for the apartment unit.
    """


