class CommercialPropertyLand(BaseModel):
    landType: LandType | None = None
    """
    Identifies the type of land (Commercial, Industrial, or Residential); landType supplies the property's secondary-type values for Land and underpins land-use classification.
    """
    areaMeasurementType: MeasurementUnit | None = None
    """
    Structured land-size value (acreage/area with unit); the core size attribute for land valuation, per-acre metrics, and the Floor Area Ratio (FAR = GBA / Lot Size) denominator. Square-feet values are integers; other units allow up to two decimals. Unit of the gross land area; Unknown when no land size is recorded.
    """
    grossArea: float | None = None
    """
    Structured land-size value (acreage/area with unit); the core size attribute for land valuation, per-acre metrics, and the Floor Area Ratio (FAR = GBA / Lot Size) denominator. Square-feet values are integers; other units allow up to two decimals. Gross land area value in its original unit with no unit conversion.
    """
    netArea: float | None = None
    """
    Structured land-size value (acreage/area with unit); the core size attribute for land valuation, per-acre metrics, and the Floor Area Ratio (FAR = GBA / Lot Size) denominator. Square-feet values are integers; other units allow up to two decimals. Net land area value in its original unit with no unit conversion; its unit is not reported separately.
    """
    improvementsDescription: str | None = None
    """
    Description of any improvements made to the land. Examples: rough graded, paved, curbs and sidewalks.
    """
    topographyType: TopographyType | None = None
    """
    Code describing the land's topography (e.g. level, sloping, rolling); topography affects developability, site-work cost, and buildable area.
    """
    onSiteImprovementType: OnSiteImprovementType | None = None
    """
    On-site improvements are refinements inside the lot boundaries that add to the land's development potential.
    """
    zoningDescription: str | None = None
    """
    Description of the lot density the land is zoned for, commonly stated in units per acre (sometimes per square foot); a key entitlement/developability attribute for valuation.
    """
    landName: str | None = None
    """
    The name of the land.
    """
    maxDwellingUnitsAllowed: int | None = None
    """
    The maximum number of dwelling units that can be built overall on this unit of land.
    """
    currentUsageDescription: str | None = None
    """
    Describes how the land is currently being used.
    """
    lengthInFeet: float | None = None
    """
    The length of the land, in feet.
    """
    widthInFeet: float | None = None
    """
    The width of the land, in feet.
    """
    isLotIrregular: bool | None = None
    """
    Flag indicating whether the land is irregularly shaped.
    """
    numberOfLots: int | None = None
    """
    The number of lots on the unit of land.
    """
    offSiteState: RecordStateType | None = None
    """
    Represents one of three states of off-site information for the land: 0 = nothing is known about off-site attributes; 1 = 'All To Site' (all off-site amenities are set up to service the land); 2 = 'All Needed' (no off-site amenities are set up to service the land).
    """
    proposedUses: list[ProposedLandUse] | None = None
    """
    Proposed/best-use designation for the parcel, guiding development potential and valuation; aligns with the hierarchical land-use code taxonomy used to classify primary land use. List of the proposed land-use values from each proposed-use entry.
    """
    developmentApprovals: list[DevelopmentApprovalType] | None = None
    """
    Type of development approval/entitlement the land has obtained (e.g. zoning, permit, plat), indicating its shovel-readiness. Each row records one approval type held for the parcel. List of the approval types from each development-approval entry.
    """
    offSiteUtilityType: OffSiteUtilityType | None = None
    """
    Represents one of three states of off-site information for the land: 0 = nothing is known about off-site attributes; 1 = 'All To Site' (all off-site amenities are set up to service the land); 2 = 'All Needed' (no off-site amenities are set up to service the land). Summarises off-site utilities: Unknown if the state is Unknown or unset; if Yes, AllToSite when every known improvement type is listed and Custom otherwise; if No, NoneToSite when none are listed and Custom otherwise.
    """
    utilities: list[CommercialPropertyLandOffSiteImprovement] | None = None
    """
    Collection of off-site improvement records (utilities/roads reaching the site) describing development readiness. Off-site improvements from the land record.
    """
    frontage: list[CommercialPropertyFrontage] | None = None
    """
    Collection of frontage records describing the land's road frontage; frontage and visibility are key land/retail-site attributes.
    """
    offSiteImprovementExceptions: (
        list[CommercialPropertyLandOffSiteImprovementException] | None
    ) = None
    """
    Collection of exceptions to off-site improvements (improvements not present/available to the site).
    """


