class CommercialListingSummaryForLease(BaseModel):
    serviceType: ServiceType | None = None
    """
    Code classifying the listing's transaction service (e.g. for lease vs for sale arrangement) used to route and filter the offering.
    """
    spaceCount: int | None = None
    """
    Number of distinct lease spaces marketed under the listing; indicates how much availability the listing aggregates.
    """
    assetCount: int | None = None
    """
    Number of properties included in the offering; greater than one for portfolio or multi-property sale listings.
    """
    minDivisibleSquareFeet: float | None = None
    """
    Smallest contiguous area a tenant can lease from the listing in square feet; the minimum bite size a larger space can be subdivided into for marketing to smaller tenants.
    """
    maxContiguousSquareFeet: float | None = None
    """
    Largest single combinable block of space available in square feet — the true contiguous (contiguous-in-building) max, the sum of contiguous spaces, rather than a naive sum of all unconnected spaces.
    """
    totalAvailableSquareFeet: float | None = None
    """
    Total square footage marketed as available across the listing — space being marketed for lease/sale regardless of whether it is vacant, occupied, sublet, or available at a future date. Distinct from vacant SF; do not feed into a vacancy numerator.
    """
    askingRateLow: float | None = None
    """
    Lowest asking (face) lease rate quoted across the listing's spaces, in the listing's rate basis; an asking-flavor rent, not contract or effective, and not comparable across service types without grossing-up/normalizing.
    """
    askingRateHigh: float | None = None
    """
    Highest asking (face) lease rate quoted across the listing's spaces, in the listing's rate basis; an asking flavor — normalize service type (NNN vs gross) and per-SF/yr before comparing rents.
    """
    askingRateBasis: RateBasis | None = None
    """
    Rent service type/basis governing the asking rate (e.g. NNN/triple-net, FSG/full-service-gross, modified gross) — who pays which operating expenses. Rates are not comparable across bases without normalizing (e.g. grossing a net rate up to full-service).
    """
    askingRateMeasurementType: MeasurementUnit2 | None = None
    """
    Size basis the asking rate is measured against (e.g. per SF per year vs per month), needed to interpret and normalize the rate. Per-acre rates are reported as Acres and per-square-foot rates as squareFeet; any other basis is Unknown.
    """
    vacancyLoss: float | None = None
    """
    Vacancy/collection-loss allowance deducted in the income waterfall (gross potential/base rent + reimbursements + other income, less this loss = Effective Gross Income); an underwriting input reflecting expected uncollected rent.
    """
    spaces: list[CommercialListingSummaryForLeaseSpaceForLease] | None = None
    """
    One entry per space. All spaces are listed, including off-market and lease-pending ones. For non-exclusive (open) mandates the entries are the listing's own marketing copies of the spaces; otherwise they are the inventory spaces. Sorted by floor order, then suite name, then id.
    """
    properties: list[CommercialListingSummaryForLeaseProperty] | None = None
    """
    Properties of the listing's property group, only fetched for building-park and shopping-center lease listings, so empty for all other lease types. The group's primary property comes first, then non-land properties by building size (largest first), then land by id.
    """
    lands: list[CommercialListingSummaryForLeaseLandForLease] | None = None
    """
    Land-for-lease records attached to the listing, only for for-lease listing types.
    """
    minDateOnMarket: AwareDatetime | None = None
    """
    The date a ForSale item (Property, Land, or CondoUnit) goes on the market. Anchors marketing duration and on-market status. Earliest on-market date across the listing's for-sale records if it has any, otherwise across its for-lease spaces, otherwise across its land-for-lease records; null when none has a date. Uses inventory records, including off-market ones.
    """


