class LeaseDealRateEscalation(BaseModel):
    cpiAnnualMaxPercent: float | None = None
    """
    Cap on the annual CPI-driven rent increase (collar maximum), limiting the bump regardless of how high CPI runs.
    """
    cpiAnnualMinPercent: float | None = None
    """
    Floor on the annual CPI-driven rent increase (collar minimum), guaranteeing a minimum bump regardless of how low CPI runs.
    """
    escalationAmount: float | None = None
    """
    Fixed dollar amount of the rate escalation. Nullable, because when an EscalationPct is specified the escalationAmount may not necessarily apply.
    """
    escalationPercent: float | None = None
    """
    Percentage of the rate escalation. Nullable, because when an escalationAmount is specified the EscalationPct may not necessarily apply.
    """
    fromLeaseDate: AwareDatetime | None = None
    """
    Calendar date on which this escalation step begins, an alternative to fromLeaseMonth for anchoring the bump to an absolute date.
    """
    fromLeaseMonth: int | None = None
    """
    Start of the negotiated term during which the rate escalation applies. A unique constraint on LeaseDealID, RateEscalationTypeID, fromLeaseMonth, and toLeaseMonth prevents multiple rows for the same term on a given lease deal and escalation type.
    """
    id: int | None = None
    """
    Surrogate primary key of the rate-escalation record, added to simplify updating and deleting records.
    """
    intervalMonthCount: int | None = None
    """
    Number of months between recurring applications of this escalation when it repeats, e.g. an annual bump is a 12-month interval.
    """
    isRepeatToEnd: bool | None = None
    """
    Whether this escalation step repeats on its interval through the end of the lease term rather than applying just once.
    """
    pctOfMarketRate: float | None = None
    """
    Percentage of prevailing market rent to which rent is reset at this escalation, used for market-rate (fair-market-value) review escalations.
    """
    percentOfCpiInputRate: float | None = None
    """
    Percentage of the Consumer Price Index movement applied as the rent increase for a CPI-indexed escalation, e.g. 80 percent of CPI.
    """
    rateActualAfterEscalation: float | None = None
    """
    Resulting actual contract rent rate after this escalation has been applied; the stepped-up rent figure feeding effective-rent calculations.
    """
    rateEscalationAmountType: RateEscalationAmountType | None = None
    """
    Unit/basis for the escalation amount (e.g. per square foot, per month, total), needed to normalize the bump into a comparable rent figure.
    """
    rateEscalationType: RateEscalationType | None = None
    """
    Code describing if and how the contract rent steps up over the term (escalation method) — e.g. fixed periodic bumps, CPI-indexed, or market-rate reviews. Displayed as a single escalation % with pattern, or 'Varying' for multiple steps.
    """
    toLeaseMonth: int | None = None
    """
    End of the negotiated term during which the rate escalation applies. A unique constraint on LeaseDealID, RateEscalationTypeID, fromLeaseMonth, and toLeaseMonth prevents multiple rows for the same term on a given lease deal and escalation type.
    """


