    leaseTermType: LeaseTermType | None = None
    """
    Unit in which the lease term is expressed (days, months, years); combined with leaseTerm to compute term length in months.
    """
    marketEffectiveRate: float | None = None
    """
    System-calculated market effective rent per SF from the effective-rent engine — base/contract rent net of concessions, TIA and free rent, spread over the term. The modeled market-based effective-rent flavor.
    """
