    """
    System-calculated market effective rent expressed per month, derived from the effective-rent calculation result.
    """
    marketEffectiveRatePerYear: float | None = None
    """
    System-calculated market effective rent expressed per year, derived from the effective-rent calculation result.
    """
    monetaryUnit: MonetaryUnit | None = None
    """
    Currency unit for all monetary amounts on the deal; normalize to a common currency before aggregating rents or values across deals.
    """
    netAggregateValue: float | None = None
