class SpaceOccupied(BaseModel):
    buildOut: BuildOut | None = None
    """
    Value describing the build-out type of the occupied space (the nature of the tenant improvements present).
    """
    buildOutConditionType: BuildOutConditionType | None = None
    """
    Condition of the space's build-out/fit-out (e.g. shell, second-generation, fully built), indicating readiness for occupancy.
    """
    buildOutStatus: BuildOutStatus | None = None
    """
    Status of the space build-out (e.g. existing, planned, under construction), describing where the fit-out stands.
    """
    id: int | None = None
    """
    Unique identifier of the occupied-space record representing space taken off-market and physically occupied under a lease.
    """
    loadBay: SpaceOccupiedLoadBay | None = None
    """
    Loading-bay attributes of the occupied industrial space (dock/load configuration); a key industrial logistics attribute of the space.
    """
    monthsOnMarket: int | None = None
    """
    Number of months the space was marketed before being taken off-market and occupied; derived from on-market and off-market dates.
    """
    propertyFloorId: int | None = None
    """
    A number uniquely identifying a floor on any property; foreign key locating the occupied space on its floor within the building.
    """
    spaceLayout: SpaceLayout | None = None
    """
    Code describing the physical layout/configuration of the occupied space (e.g. open plan, divided offices).
    """
    spacePosition: SpacePosition | None = None
    """
    Retail space position (End Cap, In-line, Outparcel/Pad, Anchor, In-Store) describing where the occupied space sits within a center.
    """
    squareFeetOccupied: float | None = None
    """
    Rentable square footage physically occupied in this space; the area driver for occupancy and net/gross absorption measurement. Restricted and suppressed space-for-lease is excluded from aggregate SF.
    """
    squareFeetOffice: float | None = None
    """
    Office portion of the occupied space in square feet. Relevant to industrial/flex office content.
    """
    squareFeetUsable: float | None = None
    """
    Usable (tenant-exclusive) square footage of the occupied space, excluding shared common area; distinct from rentable area.
    """
    suite: str | None = None
    """
    Suite (or unit) number of the occupied space. NULL when the tenant cannot be identified; otherwise derived from the tenant's address. Its data size should match the corresponding field in SpaceForLease, SpaceOccupied, and CondoUnit.
    """


class CommercialSaleCompApartment(BaseModel):
    apartmentDataSource: ApartmentDataSourceType | None = None
    """
    Source of the apartment unit data (e.g. multifamily research vs marketplace feed), indicating provenance.
    """
    avgUnitSizeSqFt: int | None = None
    """
    Average rentable area in square feet for this unit type; size context for rent and price comparisons.
    """
    maxEffectiveRent: int | None = None
    """
    Upper bound of effective monthly rent (asking adjusted for concessions) for this unit type; keep the effective flavor separate from asking rent when aggregating.
    """
    maxMonthlyRent: int | None = None
    """
    Upper bound of asking monthly rent for this unit type; asking-flavor rent, normalize before aggregating.
    """
    maxOccupants: int | None = None
    """
    Maximum permitted occupants for this unit type.
    """
    minEffectiveRent: int | None = None
    """
    Lower bound of effective monthly rent (asking adjusted for concessions) for this unit type; keep the effective flavor distinct from asking rent before comparing.
    """
    minMonthlyRent: int | None = None
    """
    Lower bound of asking monthly rent for this unit type; normalize to $/SF/yr and keep the asking flavor distinct before comparing.
    """
    monthlyDiscount: int | None = None
    """
    Monthly rent discount/concession amount applied to this unit type, bridging asking and effective rent.
    """
    numBaths: float | None = None
    """
    Bathroom count for this unit type, fractional to allow half-baths; multifamily unit-mix attribute.
    """
    numBeds: conint(ge=0, le=255) | None = None
    """
    Bedroom count of this unit type within the multifamily comp; primary unit-mix attribute.
    """
    numOccupantsVacant: int | None = None
    """
    Vacant occupancy capacity for this unit type (occupant slots unfilled); a multifamily occupancy detail.
    """
    numUnits: int | None = None
    """
    Number of units of this type in the property; drives the multifamily unit count and per-unit pricing.
    """
    numUnitsAvailable: float | None = None
    """
    Count of units of this type marketed as available; available is distinct from vacant and includes occupied/future-available units.
    """
    numUnitsVacant: float | None = None
    """
    Count of vacant (physically empty) units of this type at the property; vacancy is physical regardless of lease obligation.
    """
    propertyId: int | None = None
    """
    Foreign key to the property the apartment data belongs to; join on integer ID.
    """
    totalConcessionValue: int | None = None
    """
    Total monetary value of concessions offered on this unit type; reduces effective rent below asking.
    """


class CommercialSaleCompContact(BaseModel):
    contactFirstName: str | None = None
    """
    First name of the party as captured on the comp; free-text name used when the contact is not resolved to a Contact ID.
    """
    contactId: int | None = None
    """
    Id of the person in CoStar contact data.
    """
    contactLastName: str | None = None
    """
    Last name of the party as captured on the comp; free-text name fallback alongside the contact ID.
    """
    contactPhone: str | None = None
    """
    Phone number for the contact party to the sale; personal contact detail captured by research.
    """
    contactRole: ContactRole2 | None = None
    """
    Role of the person or company on this record, such as listing broker, buyer or seller.
    """
    funds: list[int] | None = None
    """
    Collection of investment fund references tied to this party, linking the buyer/seller to the funds behind the transaction. Join on integer IDs.
    """
    locationId: int | None = None
    """
    The contact's location - the main work location of the contact.
    """
    locationName: str | None = None
    """
    Name of the company/location for the party as captured on the comp; free-text fallback when not resolved to a Location ID. Join on IDs, not names.
    """
    locationPhone: str | None = None
    """
    Phone number of the company/location party to the sale; contact detail captured by research.
    """
    percentOwned: conint(ge=0, le=255) | None = None
    """
    Ownership percentage held by this buyer/seller party; summed across parties cannot exceed 100 and is bounded by the partial-interest sale percent.
    """


class CommercialSaleCompEntity(BaseModel):
    allocatedPrice: int | None = None
    """
    Estimated price attributed to this individual asset within a multi-property/portfolio sale when the actual per-property price is unknown; a confidence-flagged modeled value (carry allocatedPriceStatus).
    """
    allocatedPriceStatus: SalePriceStatus | None = None
    """
    How allocatedPrice was established. 8 Allocated means it is an estimated share of the portfolio price; the other values have the meanings given for salePriceStatus.
    """
    assetType: AssetType | None = None
    """
    Type of the asset/entity in the sale (e.g. property, document); determines the grain and which fields apply. Filter on this before counting true comps.
    """
    averageRentalRate: float | None = None
    """
    Average rental rate for the asset at sale; income input for investment-sale valuation. Normalize flavor/type before comparing.
    """
    buildingFullName: str | None = None
    """
    Full name of the building/asset; hospitality-specific identifier used for hotel comps.
    """
    capitalizationRateActual: float | None = None
    """
    Actual (in-place NOI) cap rate for this individual asset (R = NOI / Value); core per-asset valuation metric. In UK/France this field carries Yield (inclusive of acquisition costs) rather than Cap Rate.
    """
    capitalizationRateProForma: float | None = None
    """
    Pro forma (projected-NOI) cap rate for this individual asset; flag as a projection when reported.
    """
    documentId: int | None = None
    """
    Foreign key to the transfer document associated with this entity, linking the asset to its recorded deed.
    """
    entityId: int | None = None
    """
    Id of the sold asset this entry describes; read it with assetType (a property, a condo unit or a rumored property).
    """
    hotelClass: HotelClass | None = None
    """
    Hotel class/tier of the asset (hospitality-specific); a benchmarking attribute for hotel sale comps, aligned to STR-style hospitality classification used in hospitality KPI calculations.
    """
    hotelOperationType: HotelOperationType | None = None
    """
    Hotel operating arrangement (e.g. franchise, managed, independent); hospitality-specific attribute affecting value.
    """
    id: int | None = None
    """
    Unique identifier of this per-asset comp-entity row within the sale comp.
    """
    notes: list[Note] | None = None
    """
    Collection of free-text research notes attached to this comp-entity, often capturing per-asset deal context.
    """
    numberOfUnits: int | None = None
    """
    Unit count for the asset; multifamily/land attribute supporting price-per-unit metrics.
    """
    percentLeased: float | None = None
    """
    Share of the asset under lease at the time of sale; the occupancy/leasing profile is a key comp comparability dimension for income durability (leased differs from physically occupied).
    """
    propertyId: int | None = None
    """
    PropertyID added to enable searches by property/address without joining to Property or CondoUnit+Property by sale entity type, dramatically improving comp retrieval speed.
    """
    totalSquarefeet: float | None = None
    """
    Total square footage of the asset; size denominator for price/SF and multifamily/land sizing.
    """


class TransferDocumentAssessment(BaseModel):
    assessment: Assessment | None = None
    """
    Value-typed assessed-valuation breakdown from the assessor (improved value, land value, total value, and derived improved-to-total ratio); the tax-roll basis of value for the parcel.
    """
    assessmentSourceType: AssessmentSourceType | None = None
    """
    Code identifying the origin of the assessment data (e.g. which assessor/tax source supplied the valuation), used to gauge provenance and reliability of the figures.
    """
    assessmentYear: int | None = None
    """
    Tax assessment year the assessed valuation figures apply to, anchoring the assessor's improved/land/total values to a specific assessment roll period.
    """
    id: int | None = None
    """
    Unique identifier for the transfer-document assessment record, which captures the assessor/tax valuation tied to a property's deed transfer within a commercial sale comp.
    """
    isPartialAPNSale: bool | None = None
    """
    Flag indicating the sale transaction covered only part of the assessor's parcel (APN) rather than the whole parcel, a comparability caveat when relating the assessment to the sale price.
    """
    marketAssessment: MarketAssessment | None = None
    """
    Value-typed market-valuation breakdown (market improvement, land, total value, and derived improvement percent) representing the assessor's estimated market value as distinct from the assessed/taxable value.
    """
    parcelNumber: str | None = None
    """
    County assessor's parcel number (APN) for the land parcel covered by this transfer document, tying the assessment to public tax/ownership records; APNs are unique only within a county.
    """
    propertyTax: float | None = None
    """
    Annual property tax amount levied on the parcel per the assessor record; a financial datum used in income/expense analysis of the comp and in comparability adjustments.
    """
    propertyTaxYear: int | None = None
    """
    Tax year the propertyTax amount applies to, anchoring the levied tax figure to a specific billing period.
    """


class TransferDocument(BaseModel):
    assessments: list[TransferDocumentAssessment] | None = None
    """
    Collection of per-document assessment records (assessed/market improvement, land, and total values) rolled up to support comp valuation.
    """
    cityTax: float | None = None
    """
    City-level transfer tax paid on the conveyance; additional tax-stamp basis that can corroborate price.
    """
    countyId: int | None = None
    """
    County whose recorder/assessor holds the document; scopes the document number, which is only unique within a county. Join to county geography on the ID.
    """
    dateFiled: AwareDatetime | None = None
    """
    Date the transfer document was recorded/filed with the county; recording date for the deed.
    """
    documentNumber: str | None = None
    """
    Normalized recording/document number identifying the deed in the county recorder's records, used to tie the sale to public records.
    """
    documentNumberRaw: str | None = None
    """
    Original unnormalized document number as recorded by the source, preserved alongside the cleaned documentNumber.
    """
    exciseNumber: str | None = None
    """
    Excise/recording reference number associated with the transfer tax payment on the document.
    """
    id: int | None = None
    """
    Unique identifier of the transfer (deed) document record underlying the sale comp.
    """
    isNonDisclosure: bool | None = None
    """
    Whether the sale falls in a non-disclosure jurisdiction where price is not publicly recorded, explaining undisclosed/estimated prices.
    """
    isPrimaryDocument: bool | None = None
    """
    Whether this is the primary deed for the sale comp (vs supporting/secondary documents), used to pick the authoritative conveyance.
    """
    legalDescription: str | None = None
    """
    Legal description of the land parcel conveyed by the deed, defining exactly what real property transferred.
    """
    noDocumentAvailable: bool | None = None
    """
    Flag indicating no recorded transfer document is available for the sale, so deed-derived details cannot be sourced.
    """
    taxStampType: TaxStampType | None = None
    """
    Type of documentary tax stamp on the deed, indicating the basis/jurisdiction of the transfer tax.
    """
    transferTax: float | None = None
    """
    Transfer (county/state) tax paid on the recorded conveyance; can be used to infer or corroborate undisclosed sale price.
    """


class CommercialSaleCompVerificationField(BaseModel):
    verificationField: VerificationField | None = None
    """
    Code identifying which specific sale-comp field this verification record pertains to, enabling field-level tracking of what data has been verified and from which source in the comp research workflow.
    """
    verificationSource: VerificationSource | None = None
    """
    Code identifying the source through which a field of the commercial sale comp was verified (e.g. broker, buyer, seller, public record), recording how the deal datum was confirmed in the field-level verification workflow.
    """


